// 1. Extract and sanitize incoming question and language
const webhookData = $('Webhook Trigger').item.json;
const body = webhookData.body || webhookData;
const rawQuestion = (body.question || '').trim();
let language = (body.language || '').toLowerCase().trim();
const sessionId = body.sessionId || ('sess_' + Math.random().toString(36).substring(2, 10));
const clientTimestamp = body.timestamp || new Date().toISOString();

if (!rawQuestion || rawQuestion.length === 0) {
  throw new Error('Question cannot be empty');
}

// 2. Bound question length
const question = rawQuestion.substring(0, 300);

// Auto-detect language if not explicitly provided
if (!language || !['en', 'de', 'hu'].includes(language)) {
  const qLower = question.toLowerCase();
  if (/[áéíóöőúüű]/i.test(qLower) || qLower.includes('hány') || qLower.includes('milyen') || qLower.includes('tapasztalat') || qLower.includes('projekt')) {
    language = 'hu';
  } else if (/[äöüß]/i.test(qLower) || qLower.includes('wie viel') || qLower.includes('welche') || qLower.includes('erfahrung') || qLower.includes('jahre')) {
    language = 'de';
  } else {
    language = 'en';
  }
}

// 3. Dynamic Model Routing based on linguistic capability:
// Hungarian: 'hermes3:8b' (based on Llama 3.1 8B, flawless vowel harmony and Hungarian morphology)
// English/German: 'qwen2.5:7b' (exceptional fluency, precision, and low latency)
let targetModel = 'qwen2.5:7b';
if (language === 'hu') {
  targetModel = 'hermes3:8b';
}

// 4. Retrieve context text extracted from the localized CV context file on disk
let rawFileContext = '';
try {
  rawFileContext = ($('Extract Context Text').item.json.contextText || '').trim();
} catch (e) {
  rawFileContext = '';
}

// Slice localized section from combined file
let profileContext = rawFileContext;
if (language === 'de') {
  const deMatch = rawFileContext.match(/=== SECTION: DE ===([\s\S]*?)(?:=== SECTION:|$)/i);
  if (deMatch && deMatch[1].trim().length > 50) profileContext = deMatch[1].trim();
} else if (language === 'hu') {
  const huMatch = rawFileContext.match(/=== SECTION: HU ===([\s\S]*?)(?:=== SECTION:|$)/i);
  if (huMatch && huMatch[1].trim().length > 50) profileContext = huMatch[1].trim();
} else {
  const enMatch = rawFileContext.match(/=== SECTION: EN ===([\s\S]*?)(?:=== SECTION:|$)/i);
  if (enMatch && enMatch[1].trim().length > 50) profileContext = enMatch[1].trim();
}

// Fallback in the rare event of disk read failure
if (!profileContext || profileContext.length < 50) {
  if (language === 'de') {
    profileContext = 'Name: Géza Horváth\nTitel: ServiceNow Architect\nStandort: Pressbaum / Wien, Österreich\nE-Mail: ghorvath@gmail.com | Tel: +43 660 108 2050\nErfahrung: Über 8 Jahre dedizierte ServiceNow-Architektur & Entwicklung (seit 2018).';
  } else if (language === 'hu') {
    profileContext = 'Név: Horváth Géza\nPozíció: ServiceNow Architekt\nLakhely: Pressbaum / Bécs, Ausztria\nE-mail: ghorvath@gmail.com | Telefon: +43 660 108 2050\nTapasztalat: 8+ év dedikált ServiceNow architektúra és fejlesztés (2018 óta).';
  } else {
    profileContext = 'Name: Géza Horváth\nTitle: ServiceNow Architect\nLocation: Pressbaum / Vienna, Austria\nEmail: ghorvath@gmail.com | Phone: +43 660 108 2050\nExperience: 8+ years dedicated hands-on ServiceNow architecture & development (since 2018).';
  }
}

// 5. System prompt with strict grounding and anti-hallucination rules localized to target language
let systemPrompt = '';
if (language === 'de') {
  systemPrompt = `Sie sind Géza Horváths persönlicher KI-Karriereassistent. Ihre Aufgabe ist es, Anfragen von Personalverantwortlichen und Recruitern strikt, präzise und höflich (in der Höflichkeitsform "Sie") auf Deutsch auf Basis des folgenden VERIFIZIERTEN PROFILS UND KONTEXT-DOSSIERS zu beantworten.\n\n### STRIKTE REGELN ZUR VERMEIDUNG VON HALLUZINATIONEN:\n1. Antworten Sie AUSSCHLIESSLICH mit Fakten aus dem verifizierten Profil und Kontext-Dossier.\n2. Wenn nach einer Fähigkeit, Zertifizierung, Firma, Projekt oder Kennzahl gefragt wird, die NICHT im Dossier steht, antworten Sie ausdrücklich: "Dazu liegen mir im verifizierten Profil von Géza keine Informationen vor. Bitte wenden Sie sich direkt per E-Mail an ghorvath@gmail.com oder über LinkedIn an ihn."\n3. Erfinden Sie NIEMALS Daten, Rollen oder Projektdetails. Keine Spekulationen.\n4. Zur Berufsbezeichnung: Géza arbeitet in Enterprise Business Applications und ServiceNow-Architektur, war jedoch NICHT "Enterprise Business Applications Lead". Seine korrekte Berufsbezeichnung lautet ServiceNow Architect.\n5. Halten Sie Antworten professionell, präzise und recruiter-fokussiert (2-4 Sätze oder Aufzählungspunkte).\n6. Berichten Sie über Géza stets in der dritten Person ("Géza...", "Er...").\n\n### VERIFIZIERTES PROFIL & KONTEXT-DOSSIER:\n${profileContext}`;
} else if (language === 'hu') {
  systemPrompt = `Te Horváth Géza személyes AI karrier asszisztense vagy. A feladatod, hogy a toborzók és érdeklődők kérdéseire szigorúan, pontosan, udvariasan és természetes magyarsággal válaszolj az alábbi HITELESÍTETT SZAKMAI PROFIL ÉS KONTEXTUS DOSSZIÉ alapján.\n\n### SZIGORÚ TÉNYALAPÚ SZABÁLYOK:\n1. KIZÁRÓLAG az alábbi hitelesített profilban szereplő tényeket használd a válaszhoz.\n2. Ha olyan képességről, tanúsítványról, cégről, projektről kérdeznek, amely NEM szerepel a profilban, kifejezetten így válaszolj: "Erről nem áll rendelkezésre megerősített információ Géza szakmai profiljában. Kérlek, keresd Gézát közvetlenül a ghorvath@gmail.com e-mail címen vagy LinkedInen."\n3. SOHA ne találj ki dátumokat, szerepköröket vagy projekt részleteket. Ne bocsátkozz találgatásokba.\n4. Pozíció megnevezése: Géza vállalati üzleti alkalmazásokkal és ServiceNow architektúrával foglalkozik, de hivatalosan NEM volt "Enterprise Business Applications Lead". A pontos pozíciója: ServiceNow Architekt.\n5. A válaszok legyenek lényegretörőek, szakmaiak és toborzó-fókuszúak (2-4 mondat vagy felsorolás).\n6. Gézáról mindig harmadik személyben beszélj ("Géza...", "Ő...").\n\n### HITELESÍTETT SZAKMAI PROFIL & KONTEXTUS DOSSZIÉ:\n${profileContext}`;
} else {
  systemPrompt = `You are Géza Horváth's personal AI Career Assistant. Your job is to answer recruiter inquiries strictly, accurately, and politely from the VERIFIED PROFILE AND CONTEXT DOSSIER below.\n\n### STRICT GROUNDING RULES:\n1. Answer ONLY using facts present in the verified profile and context dossier.\n2. If asked about a skill, certification, company, project, or metric NOT in the profile/context, explicitly answer: "I do not have verified information on that in Géza's profile. Please reach out to Géza directly at ghorvath@gmail.com or on LinkedIn."\n3. NEVER invent dates, roles, or project details. Do not speculate.\n4. Regarding role title: Géza works in enterprise business applications and ServiceNow architecture, but was NOT an Enterprise Business Applications Lead. His accurate title is ServiceNow Architect.\n5. Keep answers professional, concise, articulate, and recruiter-focused (2-4 sentences or bullet points).\n6. Always represent Géza Horváth in the third person or as his career assistant.\n\n### VERIFIED PROFILE & CONTEXT DOSSIER:\n${profileContext}`;
}

return {
  json: {
    question: question,
    language: language,
    targetModel: targetModel,
    sessionId: sessionId,
    clientTimestamp: clientTimestamp,
    systemPrompt: systemPrompt,
    startTime: Date.now()
  }
};

const prev = $('Sanitize & Build Prompt').item.json;
const ollamaResponse = $input.item.json;
const answer = (ollamaResponse.response || '').trim();
const durationMs = Date.now() - prev.startTime;
const timestamp = new Date().toISOString();

const logEntry = {
  timestamp: timestamp,
  sessionId: prev.sessionId,
  language: prev.language,
  question: prev.question,
  answer: answer,
  durationMs: durationMs,
  model: prev.targetModel
};

return {
  json: {
    status: 'success',
    answer: answer,
    sessionId: prev.sessionId,
    language: prev.language,
    model: prev.targetModel,
    durationMs: durationMs,
    logLine: JSON.stringify(logEntry) + '\n'
  }
};
